"""
Module handling European language (German and Latin) functions.

translateGerman( html:str ) -> str
    Do basic word-for-word translation from Luther's German Bible to English.
translateLatin( html:str ) -> str
    Do basic word-for-word translation from Latin Vulgate Bible to English.
briefDemo() -> None
fullDemo() -> None
main calls fullDemo()


CHANGELOG:
    2025-03-20 Moved into BOS from OBD (OpenBibleData)
"""
